if __name__ == "__main__":
    os.makedirs("locales", exist_ok=True)
    for lang, idx in (("en", 0), ("ar", 1)):
        path = f"locales/{lang}.json"
        cur = json.load(open(path, encoding="utf8")) if os.path.exists(path) else {}
        cur.update({k: v[idx] for k, v in M.items()})
        json.dump(cur, open(path, "w", encoding="utf8"), ensure_ascii=False, indent=1)
    print(len(M), "messages")
